const rows = JSON.parse('{{@funding-fetch:Fetch Funding History.data}}');
const liquidityRateRaw = JSON.parse('{{@ref-rate:Get Reference Rate.result.liquidityRate}}');

const HOURS_PER_YEAR = 24 * 365;
const RAY = 1e27;

const apr = rows.map(r => parseFloat(r.fundingRate) * HOURS_PER_YEAR * 100);

const k = 2 / 73;
let emaVal = apr[0];
for (const x of apr) { emaVal = x * k + emaVal * (1 - k); }

const reference_apr = (Number(liquidityRateRaw) / RAY) * 100;

const ENTRY_SPREAD = 3;
const EXIT_SPREAD = 0;

const spread = emaVal - reference_apr;
const state = spread > ENTRY_SPREAD ? 'ENTER' : spread < EXIT_SPREAD ? 'EXIT' : 'HOLD';

return {
  coin: 'BTC',
  funding_apr: apr[apr.length - 1],
  ema_apr: emaVal,
  reference_apr,
  spread,
  state,
  observations: rows.length,
  timestamp: Date.now()
};
